schema_json:
{
  "$defs": {
    "InputRouteDiscovery": {
      "description": "One evidence-grounded route without imposing a taxonomy label.",
      "properties": {
        "route_label": {
          "description": "Concise document-grounded label for exactly one source-to-model path. Do not create an additional combined or fused route merely because a configuration uses several already-recorded routes together.",
          "title": "Route Label",
          "type": "string"
        },
        "model_name": {
          "description": "Named generative model receiving the input. Copy the paper's name.",
          "title": "Model Name",
          "type": "string"
        },
        "lifecycle_phase_verbatim": {
          "description": "One lifecycle phase stated by the paper, such as pretraining, instruction tuning, inference, or evaluation. Create separate route records when the same source-to-model path must be represented in different phases. Do not normalize the paper's phase wording yet.",
          "title": "Lifecycle Phase Verbatim",
          "type": "string"
        },
        "task_or_configuration_verbatim": {
          "description": "Task or permitted input configuration in which this route is used. Record the paper's wording.",
          "title": "Task Or Configuration Verbatim",
          "type": "string"
        },
        "source_object_verbatim": {
          "description": "One biological or textual source object before model preprocessing, copied or closely paraphrased from the paper. Do not combine independent modalities into one source object; each receives its own route.",
          "title": "Source Object Verbatim",
          "type": "string"
        },
        "transformation_chain_verbatim": {
          "description": "Ordered operations that transform the source object before it reaches the generative model. Preserve the paper's terminology and do not collapse multiple operations into a taxonomy category.",
          "items": {
            "type": "string"
          },
          "title": "Transformation Chain Verbatim",
          "type": "array"
        },
        "model_visible_form_verbatim": {
          "description": "What the generative model actually receives: symbols, token IDs, vectors, projected embeddings, feature sequences, or another form.",
          "title": "Model Visible Form Verbatim",
          "type": "string"
        },
        "insertion_or_fusion_verbatim": {
          "description": "How the represented input is connected to the generative component, using the paper's architectural terminology.",
          "title": "Insertion Or Fusion Verbatim",
          "type": "string"
        },
        "text_role_verbatim": {
          "description": "Role of text in this phase/configuration. Distinguish an actual input from supervision, a target, or generated output.",
          "title": "Text Role Verbatim",
          "type": "string"
        },
        "input_status_verbatim": {
          "description": "Whether this is an actual model input, paired training supervision, training-only target, generated output, baseline, ablation, or unclear.",
          "title": "Input Status Verbatim",
          "type": "string"
        },
        "evidence_quote": {
          "description": "One short contiguous verbatim quote that directly supports the route. Never join separate passages, invent, or summarize this field.",
          "title": "Evidence Quote",
          "type": "string"
        },
        "section_heading": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Heading containing the evidence quote, if visible.",
          "title": "Section Heading"
        },
        "supporting_figure_or_table": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Figure/table identifier only when it supports this route. A generated picture description alone is not conclusive evidence.",
          "title": "Supporting Figure Or Table"
        },
        "uncertainty": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Concise unresolved ambiguity; null when the route is explicit.",
          "title": "Uncertainty"
        }
      },
      "required": [
        "route_label",
        "model_name",
        "lifecycle_phase_verbatim",
        "task_or_configuration_verbatim",
        "source_object_verbatim",
        "model_visible_form_verbatim",
        "insertion_or_fusion_verbatim",
        "text_role_verbatim",
        "input_status_verbatim",
        "evidence_quote"
      ],
      "title": "InputRouteDiscovery",
      "type": "object"
    }
  },
  "description": "Open extraction of all candidate input routes in one paper.",
  "properties": {
    "title": {
      "description": "Paper title copied from the document.",
      "title": "Title",
      "type": "string"
    },
    "doi": {
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "default": null,
      "description": "DOI if present.",
      "title": "Doi"
    },
    "input_routes": {
      "description": "All distinct input routes used by the paper's generative model(s). Create separate routes when model, lifecycle phase, task/configuration, source object, model-visible form, or fusion mechanism differs. Include training-only/output/baseline candidates only when needed to explicitly distinguish them from usable model inputs. A route begins at exactly one source object. In a multimodal configuration, attach the shared configuration name to every participating route; never emit another combined/fused route that duplicates those participants. A fused latent representation is an intermediate state of its incoming routes, not a new source route.",
      "edge_label": "HAS_INPUT_ROUTE",
      "items": {
        "$ref": "#/$defs/InputRouteDiscovery"
      },
      "title": "Input Routes",
      "type": "array"
    }
  },
  "required": [
    "title"
  ],
  "title": "InputRouteDiscoveryDocument",
  "type": "object"
}

